import{_ as r,C as n,c as s,o as i,a3 as a,G as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Scan operations","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/barcode/scan-operations.md","filePath":"master/supply-chain/inventories/barcode/scan-operations.md","lastUpdated":1791902625000}'),c={name:"master/supply-chain/inventories/barcode/scan-operations.md"};function l(d,e,p,h,g,u){const t=n("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=a('<h1 id="scan-operations" tabindex="-1">Scan operations <a class="header-anchor" href="#scan-operations" aria-label="Permalink to &quot;Scan operations&quot;">​</a></h1><p>Use the Barcode app to process a transfer by scanning. Each scan adds to the counted quantity of a line, so you validate with fewer taps and fewer typing errors.</p><blockquote><p><strong>In simple words:</strong> Scan the goods, then press Validate.</p></blockquote><p>Open <code>Barcode → Barcode App → Inventory Operations</code>. See <a href="./">Barcode app</a>.</p><h2 id="find-the-transfer" tabindex="-1">Find the transfer <a class="header-anchor" href="#find-the-transfer" aria-label="Permalink to &quot;Find the transfer&quot;">​</a></h2><ol><li>Click an operation card, for example <strong>Receipts</strong>.</li><li>The <strong>Transfers</strong> list shows reference, partner and status, for example WH/IN/11 Consolidated Components Ready.</li><li>Click a row, or type the reference in the <strong>Search...</strong> box and click <strong>Open</strong>.</li></ol>',6)),o(t,{src:"/images1/inventory/bc_transfers.png",alt:"Barcode Transfers list showing WH/IN/11 Consolidated Components in Ready state"}),e[1]||(e[1]=a('<p>If nothing matches you see <strong>No active operation found for this barcode.</strong></p><h2 id="the-operation-screen" tabindex="-1">The operation screen <a class="header-anchor" href="#the-operation-screen" aria-label="Permalink to &quot;The operation screen&quot;">​</a></h2><p>The title is the transfer reference. A <strong>MOVES</strong> section shows one card per line. Each card has the internal reference, the product name, the source (shown as <strong>From: Partners/Vendors</strong>) and progress, for example <strong>0 / 15 Units</strong>.</p><ul><li><strong>Scan box:</strong> type or scan a barcode, then click <strong>Submit scan</strong>.</li><li><strong>Pencil icon:</strong> edit the counted quantity.</li><li><strong>Quick button</strong>, for example <strong>+15:</strong> sets the count to the full demand.</li></ul>',4)),o(t,{src:"/images1/inventory/bc_operation.png",alt:"Barcode screen for WH/IN/11 with SSD 512GB progress 0 / 15 Units and the Validate and Cancel buttons"}),e[2]||(e[2]=a('<h2 id="what-a-scan-matches" tabindex="-1">What a scan matches <a class="header-anchor" href="#what-a-scan-matches" aria-label="Permalink to &quot;What a scan matches&quot;">​</a></h2><p>Aureus tries these in order: transfer name, product barcode or reference, packaging barcode, lot or serial number, package name. A matched product raises its count. Messages include <strong>Move quantity updated.</strong>, <strong>This product is not part of the operation.</strong> and <strong>No matching barcode found.</strong></p><h2 id="validate-or-cancel" tabindex="-1">Validate or cancel <a class="header-anchor" href="#validate-or-cancel" aria-label="Permalink to &quot;Validate or cancel&quot;">​</a></h2><ul><li><strong>Validate:</strong> completes the transfer with the counted quantities. If lines are short, a window <strong>Incomplete Transfer</strong> lists Product, Done, To Do and Backorder. Choose <strong>Validate</strong>, <strong>No Backorder</strong> or <strong>Discard</strong>.</li><li><strong>Cancel:</strong> asks <strong>Are you sure you want to Cancel?</strong> Click <strong>Confirm</strong>.</li></ul><p>A message <strong>Action completed.</strong> returns you to the list. The buttons are hidden once the transfer is Done or Canceled.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>For WH/IN/11, scan the SSD 512GB barcode 15 times, or click <strong>+15</strong>, then <strong>Validate</strong>. Stock updates the same as validating on the desktop. See <a href="./../operations/receipts.html">Receipts</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Barcode app</a></li><li><a href="./scan-adjustments.html">Scan adjustments</a></li><li><a href="./../operations/receipts.html">Receipts</a></li><li><a href="./../operations/backorders-and-returns.html">Backorders and returns</a></li></ul>',9))])}const _=r(c,[["render",l]]);export{f as __pageData,_ as default};
